def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find zero regions connected to the edge using 4-neighbor movement.
    exterior = set()
    stack = []
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c))
                stack.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and (r, c) not in exterior:
                exterior.add((r, c))
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0
                    and (nr, nc) not in exterior):
                exterior.add((nr, nc))
                stack.append((nr, nc))

    holes = {(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == 0 and (r, c) not in exterior}
    if not holes:
        return out

    # Identify 1-components that border an enclosed zero region.
    seen = set()
    qualified = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            comp = set()
            todo = [(r, c)]
            seen.add((r, c))
            while todo:
                cr, cc = todo.pop()
                comp.add((cr, cc))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = cr + dr, cc + dc
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        todo.append((nr, nc))
            borders_hole = any(
                (cr + dr, cc + dc) in holes
                for cr, cc in comp
                for dr in (-1, 0, 1)
                for dc in (-1, 0, 1)
                if dr or dc
            )
            if borders_hole:
                qualified.update(comp)

    # Color the 8-neighbor halo: enclosed side 3, outside side 2.
    for r, c in qualified:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if not (dr or dc):
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0:
                    out[nr][nc] = 3 if (nr, nc) in holes else 2
    return out
